INSERT dbo.tbl_Dim_YogaDependencies(Code,DisplayName,KindCode,Description)
SELECT * FROM (VALUES
('CHART_D9',N'Navamsa chart (D9)','CONTEXT',N'The predicate requires a computed D9 chart.'),
