INSERT dbo.tbl_Rule_YogaVariant(RuleSetId,SourceRefCode,SourceVariantCode,YogaCode,YogaSetCode,SequenceNumber,DisplayName,SourceLocator,RuleRoleCode,IdentityRelationCode,EvaluationStatus,Notes)
SELECT @rs,'SRC_RAMAN_300_COMBINATIONS',v.Variant,v.Yoga,v.SetCode,v.Seq,NULL,v.Locator,'FORMATION',
       CASE WHEN COUNT(*) OVER(PARTITION BY v.Seq)>1 THEN 'ALTERNATE' ELSE 'SOURCE_VARIANT' END,v.Status,v.Notes
FROM @v v
WHERE NOT EXISTS(SELECT 1 FROM dbo.tbl_Rule_YogaVariant x WHERE x.RuleSetId=@rs AND x.SourceRefCode='SRC_RAMAN_300_COMBINATIONS' AND x.SourceVariantCode=v.Variant);

