INSERT dbo.tbl_Rule_YogaVariantDependency(YogaVariantId,YogaDependencyCode,RequirementRole)
SELECT y.Id,d.Dependency,d.Role FROM @d d JOIN dbo.tbl_Rule_YogaVariant y ON y.RuleSetId=@rs AND y.SourceRefCode='SRC_RAMAN_300_COMBINATIONS' AND y.SourceVariantCode=d.Variant
WHERE NOT EXISTS(SELECT 1 FROM dbo.tbl_Rule_YogaVariantDependency x WHERE x.YogaVariantId=y.Id AND x.YogaDependencyCode=d.Dependency);

IF (SELECT COUNT(*) FROM dbo.tbl_Rule_YogaVariant WHERE RuleSetId=@rs AND SourceRefCode='SRC_RAMAN_300_COMBINATIONS')<319
    THROW 50144,'BVR variant inventory is incomplete; expected at least 319.',1;
IF (SELECT COUNT(DISTINCT SequenceNumber) FROM dbo.tbl_Rule_YogaVariant WHERE RuleSetId=@rs AND SourceRefCode='SRC_RAMAN_300_COMBINATIONS')<300
    THROW 50145,'BVR numbered combination coverage is incomplete; expected all 300.',1;
GO

